import { useRef, useState } from 'react'
import {
  getAdminUserList,
  addAdminUser,
  editAdminUser,
  updateAdminUserStatus,
  resetAdminUserPassword,
  getRoleList,
  PermissionTypes
} from '@/apis/admin/permission'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProFormInstance, ProColumns } from '@ant-design/pro-components'
import { Button, message, Tag, Popconfirm, Modal, Form, Input, Select, Space, Tooltip } from 'antd'
import {
  PlusOutlined,
  StopOutlined,
  CheckCircleOutlined,
  EditOutlined,
  DeleteOutlined,
  KeyOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'

// 用户状态映射
const userStatusMap: Record<number, { text: string; color: string }> = {
  1: { text: '启用', color: 'success' },
  2: { text: '禁用', color: 'error' },
  3: { text: '锁定', color: 'warning' }
}

// 格式化时间
const formatTime = (time: string) => {
  if (!time) {
    return '-'
  }
  return dayjs(time).format('YYYY-MM-DD HH:mm:ss')
}

const AdminList: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const formRef = useRef<ProFormInstance>()
  const [modalVisible, setModalVisible] = useState(false)
  const [modalTitle, setModalTitle] = useState('新增管理员')
  const [editingId, setEditingId] = useState<number | null>(null)
  const [roleList, setRoleList] = useState<PermissionTypes.AdminRoleListDto[]>([])
  const [form] = Form.useForm()
  const [loading, setLoading] = useState(false)

  // 获取角色列表
  const fetchRoleList = async () => {
    try {
      const res = await getRoleList()
      if (res.code === ResultEnum.SUCCESS) {
        setRoleList(res.data?.list || [])
      }
    } catch (e) {
      console.error('获取角色列表失败', e)
    }
  }

  // 打开新增弹窗
  const openAddModal = () => {
    setEditingId(null)
    setModalTitle('新增管理员')
    form.resetFields()
    fetchRoleList()
    setModalVisible(true)
  }

  // 打开编辑弹窗
  const openEditModal = (record: PermissionTypes.AdminUserListDto) => {
    setEditingId(record.id)
    setModalTitle('编辑管理员')
    form.setFieldsValue({
      realName: record.realName,
      mobile: record.mobile,
      roleId: record.roleId
    })
    fetchRoleList()
    setModalVisible(true)
  }

  // 提交表单
  const handleSubmit = async () => {
    try {
      const values = await form.validateFields()
      setLoading(true)

      let res
      if (editingId) {
        // 编辑
        res = await editAdminUser(editingId, {
          userId: editingId,
          realName: values.realName,
          mobile: values.mobile,
          roleId: values.roleId
        })
      } else {
        // 新增
        res = await addAdminUser({
          userName: values.userName,
          realName: values.realName,
          mobile: values.mobile,
          roleId: values.roleId
        })
      }

      if (res.code === ResultEnum.SUCCESS) {
        message.success(editingId ? '编辑成功' : '新增成功')
        setModalVisible(false)
        actionRef.current?.reload()
      } else {
        message.error(res.message || '操作失败')
      }
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  // 禁用/启用用户
  const handleToggleStatus = async (record: PermissionTypes.AdminUserListDto) => {
    try {
      const newStatus = record.status === 1 ? 2 : 1
      const res = await updateAdminUserStatus(record.id, {
        userId: record.id,
        status: newStatus as 1 | 2 | 3
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success(`${record.status === 1 ? '禁用' : '启用'}成功`)
        actionRef.current?.reload()
      } else {
        message.error(res.message || '操作失败')
      }
    } catch (e) {
      message.error('操作失败')
    }
  }

  // 删除用户（使用禁用代替删除，因为接口没有删除功能）
  const handleDelete = async (record: PermissionTypes.AdminUserListDto) => {
    try {
      const res = await updateAdminUserStatus(record.id, {
        userId: record.id,
        status: 2
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success('删除成功')
        actionRef.current?.reload()
      } else {
        message.error(res.message || '操作失败')
      }
    } catch (e) {
      message.error('操作失败')
    }
  }

  // 重置密码
  const handleResetPassword = async (record: PermissionTypes.AdminUserListDto) => {
    try {
      const res = await resetAdminUserPassword(record.id, {
        userId: record.id
      })

      if (res.code === ResultEnum.SUCCESS) {
        message.success('密码重置成功')
      } else {
        message.error(res.message || '操作失败')
      }
    } catch (e) {
      message.error('操作失败')
    }
  }

  // 角色标签颜色
  const getRoleTagColor = (roleName: string) => {
    if (roleName?.includes('超级')) {
      return 'red'
    }
    if (roleName?.includes('管理员')) {
      return 'blue'
    }
    return 'default'
  }

  // 表格列定义
  const columns: ProColumns<PermissionTypes.AdminUserListDto>[] = [
    {
      title: '管理员ID',
      dataIndex: 'id',
      key: 'id',
      width: 50,
      hideInSearch: true,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '姓名',
      dataIndex: 'realName',
      key: 'realName',
      width: 120
    },
    {
      title: '用户名',
      dataIndex: 'userName',
      key: 'userName',
      width: 140
    },
    {
      title: '手机号',
      dataIndex: 'mobile',
      key: 'mobile',
      width: 140
    },
    {
      title: '角色',
      dataIndex: 'roleName',
      key: 'roleName',
      width: 100,
      hideInSearch: true,
      render: text => <Tag color={getRoleTagColor(text as string)}>{text || '-'}</Tag>
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 50,
      valueType: 'select',
      valueEnum: {
        1: { text: '启用', status: 'Success' },
        2: { text: '禁用', status: 'Error' },
        3: { text: '锁定', status: 'Warning' }
      },
      render: (_, record) => {
        const status = userStatusMap[record.status]
        return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
      }
    },
    {
      title: '创建时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 110,
      hideInSearch: true,
      render: text => (
        <span style={{ fontSize: 13, whiteSpace: 'nowrap' }}>{formatTime(text as string)}</span>
      )
    },
    {
      title: '最后登录',
      dataIndex: 'lastLoginTime',
      key: 'lastLoginTime',
      width: 110,
      hideInSearch: true,
      render: text => (
        <span style={{ fontSize: 13, whiteSpace: 'nowrap' }}>{formatTime(text as string)}</span>
      )
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 110,
      render: (_, record) => [
        <Button
          key={`${record.id}-edit`}
          type="link"
          title="编辑"
          icon={<EditOutlined />}
          onClick={() => openEditModal(record)}
        />,
        record.status === 1 ? (
          <Popconfirm
            key={`${record.id}-disable`}
            title="确定要禁用该管理员吗？"
            onConfirm={() => handleToggleStatus(record)}
          >
            <Button type="link" danger title="禁用" icon={<StopOutlined />}/>
          </Popconfirm>
        ) : (
          <Button
            key={`${record.id}-enable`}
            type="link"
            title="启用"
            icon={<CheckCircleOutlined />}
            style={{ color: '#52c41a' }}
            onClick={() => handleToggleStatus(record)}
          />
        ),
        <Popconfirm
          key={`${record.id}-reset`}
          title="确定要重置该管理员的密码吗？"
          onConfirm={() => handleResetPassword(record)}
        >
          <Button type="link" title="重置密码" icon={<KeyOutlined />} />
        </Popconfirm>,
        <Popconfirm
          key={`${record.id}-delete`}
          title="确定要删除该管理员吗？"
          description="此操作不可恢复，请谨慎操作。"
          onConfirm={() => handleDelete(record)}
        >
          <Button type="link" danger title="删除" icon={<DeleteOutlined />} />
        </Popconfirm>
      ]
    }
  ]

  return (
    <>
      <ExcelTable
        key="admin-list"
        formRef={formRef}
        columns={columns}
        requestFn={async params => {
          const { page, pageSize, realName, mobile, status, ...rest } = params
          return await getAdminUserList({
            page,
            pageSize,
            ...rest
          })
        }}
        actionRef={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        toolBarRenderFn={() => [
          <Button key="add" type="primary" icon={<PlusOutlined />} onClick={openAddModal}>
            新增管理员
          </Button>
        ]}
        scroll={{ x: 1200 }}
      />

      <Modal
        title={modalTitle}
        open={modalVisible}
        onOk={handleSubmit}
        onCancel={() => setModalVisible(false)}
        confirmLoading={loading}
        width={560}
      >
        <Form form={form} layout="vertical" style={{ marginTop: 16 }}>
          {!editingId && (
            <Form.Item
              label="用户名"
              name="userName"
              rules={[{ required: true, message: '请输入用户名' }]}
            >
              <Input placeholder="请输入用户名，用于登录" />
            </Form.Item>
          )}
          <Form.Item
            label="真实姓名"
            name="realName"
            rules={[{ required: true, message: '请输入真实姓名' }]}
          >
            <Input placeholder="请输入真实姓名" />
          </Form.Item>
          <Form.Item
            label="手机号"
            name="mobile"
            rules={[
              { required: true, message: '请输入手机号' },
              { pattern: /^1[3-9]\d{9}$/, message: '请输入正确的手机号' }
            ]}
          >
            <Input placeholder="请输入手机号" disabled={!!editingId} />
          </Form.Item>
          <Form.Item label="角色" name="roleId" rules={[{ required: true, message: '请选择角色' }]}>
            <Select placeholder="请选择角色">
              {roleList.map(role => (
                <Select.Option key={role.id} value={role.id}>
                  {role.roleName}
                </Select.Option>
              ))}
            </Select>
          </Form.Item>
        </Form>
      </Modal>
    </>
  )
}

export default AdminList
